// Generate browser-ready shared components and a static-only deployment folder.
// Run from any directory: node scripts/prepare-static.mjs
import { readFile, writeFile, mkdir, copyFile, readdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = fileURLToPath(new URL('../', import.meta.url));
const components = {};
for (const name of ['header.html', 'footer.html']) {
    components[name] = await readFile(path.join(root, name), 'utf8');
}
await writeFile(path.join(root, 'media/components.js'),
    '// Generated by scripts/prepare-static.mjs; edit header.html and footer.html.\nwindow.RASDAD_COMPONENTS = ' + JSON.stringify(components) + ';\n');
const output = path.join(root, '_site');
await mkdir(path.join(output, 'media'), { recursive: true });
for (const name of ['index.html', 'packages.html', 'services.html', 'header.html', 'footer.html']) {
    await copyFile(path.join(root, name), path.join(output, name));
}
for (const name of await readdir(path.join(root, 'media'))) {
    if (/\.(png|css|js)$/.test(name)) {
        await copyFile(path.join(root, 'media', name), path.join(output, 'media', name));
    }
}
await writeFile(path.join(output, '.nojekyll'), '');
console.log('Static website prepared in _site/; no Python or database included.');
